package ledger

import (
	"errors"
	"fmt"
	"sort"
)

// Entry is a single ledger entry.
type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

// FormatLedger renders a ledger for the given currency and locale.
// Entries are sorted by date, then description, then change.
// The input slice is not modified.
func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	c, err := newCurrency(currency)
	if err != nil {
		return "", err
	}
	l, err := newLocale(locale)
	if err != nil {
		return "", err
	}

	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		if sorted[i].Date != sorted[j].Date {
			return sorted[i].Date < sorted[j].Date
		}
		if sorted[i].Description != sorted[j].Description {
			return sorted[i].Description < sorted[j].Description
		}
		return sorted[i].Change < sorted[j].Change
	})

	var b strings.Builder
	b.WriteString(l.header())
	for _, e := range sorted {
		row, err := l.formatRow(c, e)
		if err != nil {
			return "", err
		}
		b.WriteString(row)
	}
	return b.String(), nil
}
```

