// Package ledger formats ledger entries as a nicely aligned table for a
// given currency (USD or EUR) and locale (en-US or nl-NL).
package ledger

import (
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// Entry is a single ledger entry.
type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

// FormatLedger renders entries as a formatted ledger table for the given
// currency and locale. Entries are ordered by date, then description, then
// change. The input slice is not modified.
func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	c, err := newCurrency(currency)
	if err != nil {
		return "", err
	}
	l, err := newLocale(locale)
	if err != nil {
		return "", err
	}

	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		return less(sorted[i], sorted[j])
	})

	var b strings.Builder
	b.WriteString(l.header())
	for _, e := range sorted {
		row, err := l.formatRow(c, e)
		if err != nil {
			return "", err
		}
		b.WriteString(row)
	}
	return b.String(), nil
}

// less reports whether entry a sorts before entry b: by date, then
// description, then change.
func less(a, b Entry) bool {
	if a.Date != b.Date {
		return a.Date < b.Date
	}
	if a.Description != b.Description {
		return a.Description < b.Description
	}
	return a.Change < b.Change
}

// currency is a supported currency and its symbol.
type currency struct {
	symbol string
}

func newCurrency(s string) (currency, error) {
	switch s {
	case "USD":
		return currency{symbol: "$"}, nil
	case "EUR":
		return currency{symbol: "€"}, nil
	}
	return currency{}, errors.New("unsupported currency: " + s)
}

// locale holds the formatting rules for one locale.
